head.script:
var ACTION_URL = "/data/Submission_ajax_withCredentials_WAEA-866_(WSQ-6326).json";

// fn: "p" = $p.ajax / "net" = WebSquare.net.ajax
scwin.callAjax = function(fn, opt) {
	var base = {
		url: ACTION_URL,
		action: ACTION_URL,
		contentType: "application/json",
		dataType: "json",
		success: function() {},
		error: function() {}
	};
	for (var k in opt) {
		base[k] = opt[k];
	}
	if (fn === "p") {
		$p.ajax(base);
	} else {
		WebSquare.net.ajax(base);
	}
};
scwin.btn1 = function() {
	scwin.callAjax("p", { mode: "synchronous", withCredentials: true });
};
scwin.btn2 = function() {
	scwin.callAjax("net", { mode: "synchronous", withCredentials: true });
};
scwin.btn3 = function() {
	scwin.callAjax("p", { mode: "asynchronous", withCredentials: true });
};
scwin.btn4 = function() {
	scwin.callAjax("p", { withCredentials: true });
};
scwin.btn5 = function() {
	scwin.callAjax("p", { mode: "synchronous", withCredentials: false });
};
scwin.btn6 = function() {
	scwin.callAjax("p", { mode: "synchronous" });
};
